CREATE OR REPLACE FUNCTION public.sp_upsert_daily_readiness_log(p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid, p_classroom_id uuid, p_check_date date, p_item_id character varying, p_is_completed boolean, p_user_id uuid)  RETURNS void  LANGUAGE plpgsql AS $function$ BEGIN     INSERT INTO public.daily_readiness_checklist_logs (         tenant_id, organization_id, branch_id, classroom_id, check_date, item_id, is_completed, updated_by_user_id, updated_at     )     VALUES (         p_tenant_id, p_organization_id, p_branch_id, p_classroom_id, p_check_date, p_item_id, p_is_completed, p_user_id, NOW()     )     ON CONFLICT (tenant_id, organization_id, check_date, item_id)     DO UPDATE SET         is_completed = EXCLUDED.is_completed,         updated_by_user_id = EXCLUDED.updated_by_user_id,         updated_at = NOW(),         branch_id = COALESCE(EXCLUDED.branch_id, daily_readiness_checklist_logs.branch_id),         classroom_id = COALESCE(EXCLUDED.classroom_id, daily_readiness_checklist_logs.classroom_id); END; $function$ ;
